@page "/apply"
@using sv_94d6acb2fe6e4316aae5db3a764b7b26.Components.JobApplication
@using sv_94d6acb2fe6e4316aae5db3a764b7b26.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Model="personalInfo"
                              ValidateEmail="ApplicationService.ValidateEmailAsync"
                              OnNext="() => AdvanceStep()" />
            break;
        case 1:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="() => AdvanceStep()"
                             OnBack="() => GoToStep(0)" />
            break;
        case 2:
            <ReferencesStep References="references"
                            OnNext="() => AdvanceStep()"
                            OnBack="() => GoToStep(1)" />
            break;
        case 3:
            <CoverLetterStep @bind-CoverLetterText="coverLetter"
                             OnNext="() => AdvanceStep()"
                             OnBack="() => GoToStep(2)" />
            break;
        case 4:
            <ReviewStep Personal="personalInfo"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="coverLetter"
                        OnBack="() => GoToStep(3)"
                        OnEditSection="GoToStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int currentStep;
    private HashSet<int> completedSteps = new();

    private PersonalInfoStep.PersonalInfoModel personalInfo = new();
    private List<WorkEntryForm.WorkEntryModel> workEntries = new() { new() };
    private List<ReferenceForm.ReferenceModel> references = new() { new(), new() };
    private string coverLetter = "";

    private void AdvanceStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void GoToStep(int step)
    {
        if (step <= currentStep || completedSteps.Contains(step))
        {
            currentStep = step;
        }
    }

    private async Task<int> SubmitApplication()
    {
        var application = new JobApplication(
            new PersonalInfo(personalInfo.FullName, personalInfo.Email, personalInfo.Phone, personalInfo.Address),
            new WorkHistory(workEntries.Select(e => new WorkEntry(
                e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()),
            references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList(),
            coverLetter
        );

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

